import 'dart:typed_data';

import 'package:pdf/pdf.dart';
import 'package:pdf/widgets.dart' as pw;

/// Client-side fallback used only by legacy/demo views without a persisted
/// scan id. Persisted reports are generated by the backend using the same
/// officer-style structure.
class ReportGenerator {
  static Future<Uint8List> generatePdfReport({
    required String reportId,
    required String product,
    required String findingsOrNotes,
    required bool noFlagsDetected,
    required String timestamp,
    List<Uint8List>? proofImages,
  }) async {
    final pdf = pw.Document(
      title: 'True Label Compliance Screening Report - $reportId',
      author: 'True Label',
    );
    final status = noFlagsDetected
        ? 'NO CONFIRMED FLAGS DETECTED'
        : 'POTENTIAL ISSUES - REVIEW REQUIRED';
    final statusColor =
        noFlagsDetected ? PdfColors.green800 : PdfColors.orange800;
    final statusFill = noFlagsDetected ? PdfColors.green50 : PdfColors.orange50;
    final images = proofImages ?? const <Uint8List>[];

    pdf.addPage(
      pw.MultiPage(
        pageFormat: PdfPageFormat.a4,
        margin: const pw.EdgeInsets.fromLTRB(42, 38, 42, 42),
        header: (context) => context.pageNumber == 1
            ? pw.Column(
                children: [
                  pw.Text(
                    'TrueLabel',
                    style: pw.TextStyle(
                      fontSize: 20,
                      fontWeight: pw.FontWeight.bold,
                    ),
                  ),
                  pw.SizedBox(height: 6),
                  pw.Text(
                    'OFFICIAL PRODUCT COMPLIANCE INSPECTION REPORT',
                    style: pw.TextStyle(
                      fontSize: 13,
                      fontWeight: pw.FontWeight.bold,
                    ),
                    textAlign: pw.TextAlign.center,
                  ),
                  pw.SizedBox(height: 4),
                  pw.Text(
                    'PRELIMINARY COMPLIANCE REPORT',
                    style: pw.TextStyle(
                      fontSize: 9,
                      fontWeight: pw.FontWeight.bold,
                      fontStyle: pw.FontStyle.italic,
                      color: PdfColors.grey700,
                    ),
                  ),
                  pw.SizedBox(height: 5),
                  pw.Text(
                    'Prepared by True Label for inspection and review',
                    style: const pw.TextStyle(
                      fontSize: 9,
                      color: PdfColors.grey700,
                    ),
                  ),
                  pw.SizedBox(height: 14),
                  pw.Divider(color: PdfColors.grey600, thickness: 1),
                  pw.SizedBox(height: 10),
                ],
              )
            : pw.SizedBox(height: 8),
        footer: (context) => pw.Column(
          children: [
            pw.Divider(color: PdfColors.grey400),
            pw.SizedBox(height: 4),
            pw.Row(
              mainAxisAlignment: pw.MainAxisAlignment.spaceBetween,
              children: [
                pw.Text(
                  'True Label - automated packaging-compliance screening',
                  style: const pw.TextStyle(
                    fontSize: 7.5,
                    color: PdfColors.grey600,
                  ),
                ),
                pw.Text(
                  'Page ${context.pageNumber} of ${context.pagesCount}',
                  style: const pw.TextStyle(
                    fontSize: 7.5,
                    color: PdfColors.grey600,
                  ),
                ),
              ],
            ),
          ],
        ),
        build: (context) => [
          _sectionHeading('1. REPORT DETAILS'),
          pw.Table(
            border: pw.TableBorder.all(color: PdfColors.grey500),
            columnWidths: const {
              0: pw.FixedColumnWidth(140),
              1: pw.FlexColumnWidth(),
            },
            children: [
              _detailRow('Product', product),
              _detailRow('Report ID', reportId),
              _detailRow('Report type', 'Automated screening - review document'),
              _detailRow('Inspection date', timestamp),
              _detailRow('Overall status', status),
            ],
          ),
          _sectionHeading('2. EXECUTIVE CONCLUSION'),
          pw.Text(
            noFlagsDetected
                ? 'The configured checks did not identify an evidence-backed violation in the supplied evidence. This does not establish legal compliance.'
                : 'The configured checks identified observations that require human review. Missing extracted text is not treated as a confirmed physical absence.',
            style: const pw.TextStyle(fontSize: 10, lineSpacing: 3),
          ),
          pw.SizedBox(height: 10),
          pw.Container(
            width: double.infinity,
            padding: const pw.EdgeInsets.all(10),
            decoration: pw.BoxDecoration(
              color: statusFill,
              border: pw.Border.all(color: statusColor, width: 1.2),
            ),
            child: pw.Text(
              status,
              style: pw.TextStyle(
                fontSize: 11,
                fontWeight: pw.FontWeight.bold,
                color: statusColor,
              ),
            ),
          ),
          _sectionHeading('3. AI PRODUCT INTELLIGENCE SUMMARY'),
          _keyValue('Target product', product),
          _keyValue(
            'Screening method',
            'Image evidence and configured local OCR/rule checks',
          ),
          _keyValue('Observations requiring attention', findingsOrNotes),
          _keyValue(
            'Confidence statement',
            'No automated confidence value is a legal conclusion. Review the evidence record and limitations.',
          ),
          _sectionHeading('4. DETAILED COMPLIANCE FINDINGS'),
          pw.Text(
            findingsOrNotes.trim().isEmpty
                ? 'No finding text was recorded for this legacy report.'
                : findingsOrNotes,
            style: const pw.TextStyle(fontSize: 9.5, lineSpacing: 3),
          ),
          _sectionHeading('5. PENALTY / ENFORCEMENT SUMMARY'),
          pw.Text(
            noFlagsDetected
                ? 'No evidence-backed enforcement finding was produced. Any unresolved check requires clearer evidence or manual confirmation.'
                : 'This prototype does not calculate a monetary penalty. Confirm the physical package, product classification and current law before any enforcement action.',
            style: const pw.TextStyle(fontSize: 9.5, lineSpacing: 3),
          ),
          if (images.isNotEmpty) ...[
            _sectionHeading('6. IMAGE EVIDENCE RECORD'),
            pw.Text(
              'EVIDENCE MANIFEST',
              style: pw.TextStyle(
                fontSize: 9.5,
                fontWeight: pw.FontWeight.bold,
              ),
            ),
            pw.SizedBox(height: 7),
            ...images.asMap().entries.map(
              (entry) => pw.Column(
                crossAxisAlignment: pw.CrossAxisAlignment.start,
                children: [
                  pw.Text(
                    '${entry.key + 1}. Evidence Image ${entry.key + 1}',
                    style: pw.TextStyle(
                      fontSize: 10,
                      fontWeight: pw.FontWeight.bold,
                      fontStyle: pw.FontStyle.italic,
                    ),
                  ),
                  pw.SizedBox(height: 7),
                  pw.Container(
                    alignment: pw.Alignment.center,
                    constraints: const pw.BoxConstraints(maxHeight: 330),
                    child: pw.Image(
                      pw.MemoryImage(entry.value),
                      fit: pw.BoxFit.contain,
                    ),
                  ),
                  pw.SizedBox(height: 12),
                ],
              ),
            ),
          ],
          _sectionHeading('7. IMPORTANT NOTE'),
          pw.Text(
            'Prototype decision support only - this report is not an official certificate, judicial determination or enforcement notice. An authorised reviewer should verify the physical package, complete package-side coverage, applicable product-specific law and current rules before taking formal action.',
            style: const pw.TextStyle(fontSize: 9.5, lineSpacing: 3),
          ),
        ],
      ),
    );

    return pdf.save();
  }

  static pw.Widget _sectionHeading(String text) {
    return pw.Padding(
      padding: const pw.EdgeInsets.only(top: 16, bottom: 7),
      child: pw.Text(
        text,
        style: pw.TextStyle(
          fontSize: 13,
          fontWeight: pw.FontWeight.bold,
        ),
      ),
    );
  }

  static pw.TableRow _detailRow(String label, String value) {
    return pw.TableRow(
      children: [
        pw.Container(
          color: PdfColors.grey300,
          padding: const pw.EdgeInsets.all(7),
          child: pw.Text(
            label,
            style: pw.TextStyle(
              fontSize: 9,
              fontWeight: pw.FontWeight.bold,
            ),
          ),
        ),
        pw.Padding(
          padding: const pw.EdgeInsets.all(7),
          child: pw.Text(value, style: const pw.TextStyle(fontSize: 9)),
        ),
      ],
    );
  }

  static pw.Widget _keyValue(String label, String value) {
    return pw.Padding(
      padding: const pw.EdgeInsets.only(bottom: 4),
      child: pw.RichText(
        text: pw.TextSpan(
          children: [
            pw.TextSpan(
              text: '$label: ',
              style: pw.TextStyle(fontWeight: pw.FontWeight.bold),
            ),
            pw.TextSpan(text: value),
          ],
          style: const pw.TextStyle(fontSize: 9.5),
        ),
      ),
    );
  }
}
